module top_module(
  input clk,
  input reset,
  input in1,
  input in2,
  output reg out
);reg [1:0] state;
reg [1:0] next_state;

parameter DEBOUNCE_CYCLES = 3;

always @(posedge clk, posedge reset) begin
  if (reset) begin
    state <= 2'b00;
  end else begin
    state <= next_state;
  end
end

always @(*) begin
  case (state)
    2'b00: begin
      if (in1 && in2) begin
        next_state = 2'b01;
      end else begin
        next_state = 2'b00;
      end
    end
    2'b01: begin
      if (in1 && in2) begin
        next_state = 2'b10;
      end else begin
        next_state = 2'b00;
      end
    end
    2'b10: begin
      if (in1 && in2) begin
        next_state = 2'b11;
      end else begin
        next_state = 2'b00;
      end
    end
    2'b11: begin
      if (in1 && in2) begin
        next_state = 2'b11;
      end else begin
        next_state = 2'b00;
      end
    end
  endcase
end

reg [1:0] debounce_counter;

always @(posedge clk) begin
  if (reset) begin
    debounce_counter <= 2'b00;
  end else begin
    debounce_counter <= debounce_counter + 1;
    if (debounce_counter == DEBOUNCE_CYCLES) begin
      debounce_counter <= 2'b00;
      out <= in1 ^ in2;
    end
  end
end

endmodule

