module state_control (
        input clk,
        input reset,
        input d,
        output reg z);parameter I=0, J=1, K=2, L=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= I;
		else 
			state <= next;

	always_comb begin
		case(state)
			I: next = d ? K : J;
			J: next = d ? I : L;
			K: next = d ? L : I;
			L: next = d ? K : J;
			default: next = 'x;
		endcase
	end

	assign z = (state == I || state == K);

endmodule

