module top_module(
    input reset,
    input clk,
    input echo,
    output reg done,
    output reg trigger,
    output reg [15:0] distance
);// Parameters
    parameter divH = 100; // 1000ns/10ns
    parameter divL = 400; // 4000ns/10ns
    parameter maxDist = 400; // Maximum distance in centimeters
    parameter speedOfSound = 340; // Speed of sound in meters per second
    parameter clockPeriod = 10; // Clock period in nanoseconds

    // Counters
    reg [15:0] countTrigger = 0;
    reg [15:0] countEcho = 0;

    // Internal signals
    wire pulse;

    // Trigger
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            countTrigger <= 0;
            trigger <= 0;
        end else begin
            if (countTrigger < divH) begin
                countTrigger <= countTrigger + 1;
                trigger <= 1;
            end else if (countTrigger < divL) begin
                countTrigger <= countTrigger + 1;
                trigger <= 0;
            end else begin
                countTrigger <= 0;
                trigger <= 0;
            end
        end
    end

    // Echo
    always @(posedge clk) begin
        if (echo) begin
            countEcho <= countEcho + 1;
            done <= 0;
        end else if (countEcho != 0) begin
            distance <= (countEcho * clockPeriod * speedOfSound) / 20000; // Here, the distance calculation is done directly
            countEcho <= 0;
            done <= 1;
        end
    end

    // Pulse generator
    assign pulse = (countTrigger >= divH && countTrigger < divL);

    // Distance measurement
    always @(posedge clk) begin
        if (pulse) begin
            countEcho <= 0;
            done <= 0;
        end
    end

    // Distance limit (removed since it conflicted with the measure in echo section)
    always @(posedge clk) begin
        if (distance > maxDist) begin
            distance <= maxDist;
        end
    end

endmodule

