module fsm_module (
        input clk,
        input reset,
        input signal,
        output reg out);parameter Y0=0, Y1=1, Y2=2, Y3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= Y0;
		else state <= next;

	always_comb begin
		case (state)
			Y0: next = signal ? Y1 : Y0;
			Y1: next = signal ? Y2 : Y1;
			Y2: next = signal ? Y3 : Y2;
			Y3: next = signal ? Y0 : Y3;
			default: next = 'x;
		endcase
	end

	assign out = (state == Y0) || (state == Y2);

endmodule

