            4'b0100: out = 1;
            4'b1110: out = 0;
            4'b0111: out = 1;
            4'b1001: out = 0;
            4'b0010: out = 1;
            4'b1111: out = 0;
            4'b0101: out = 1;
            default: out = 0;
        endcase
    end
endmodule

