module top_module (
  input in1,
  input in2,
  input in3,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter P=0, Q=1, R=2, S=3;

    always_comb begin
        case (state)
            P: next_state = (in1 || in2 || in3) ? R : Q;
            Q: next_state = (in1 || in2 || in3) ? S : R;
            R: next_state = (in1 || in2 || in3) ? P : S;
            S: next_state = (in1 || in2 || in3) ? Q : P;
        endcase
    end

    assign out = (state == P) || (state == R);

endmodule

