);

code:
module top_module(
     input            I_reset_n,
     input            I_clk,
     output           O_led
);parameter T1000MS = 15000000;  

    reg [25:0] R_cnt;    
    reg R_led;

    assign O_led = R_led;

    always@(posedge I_clk or negedge I_reset_n)
    begin 
         if(!I_reset_n)
         begin   
           R_cnt <= 26'b0;
           R_led <= 1'b0;
         end 
         else if(R_cnt >= T1000MS)
         begin
            R_led <= !R_led;
            R_cnt <= 26'b0;
         end
         else
         begin
            R_cnt <= R_cnt + 1'b1;
         end
    end

endmodule

