module top_module(
    input [lpm_width-1:0] data,
    input enable,
    output [lpm_width-1:0] result,
    inout [lpm_width-1:0] pad
);parameter lpm_width = 1;

// Use reg type for pad wiring to allow assignment
reg [lpm_width-1:0] pad_reg;

reg [lpm_width-1:0] result_reg;

initial begin
    if (lpm_width <= 0) begin
        $display("Value of lpm_width parameter must be greater than 0(ERROR)");
        $display("Time: %0t  Instance: %m", $time);
        $finish;
    end
end

always @(*) begin
    if (enable) begin
        pad_reg = data;         // Assign to pad_reg instead of pad
        result_reg = {lpm_width{1'bz}}; // Keeping result_reg in high-impedance
    end else begin
        pad_reg = {lpm_width{1'bz}}; // Keeping pad_reg in high-impedance
        result_reg = pad;        // Directly assignment from pad
    end
end

// Use a continuous assignment to tie pad to pad_reg
assign pad = pad_reg;

assign result = result_reg;

endmodule

