module top_module(
    input clk,         // Added clk input
    input in,
    input [3:0] delay,
    output reg out
);reg [3:0] counter;
reg [3:0] shift_reg;

always @(posedge clk) begin
    if (counter == delay) begin
        shift_reg <= {in, shift_reg[3:1]};
        out <= shift_reg[0];
        counter <= 0; // Reset counter when delay is reached
    end
    else begin
        shift_reg <= {1'b0, shift_reg[3:1]};
        out <= 1'b0;
        counter <= counter + 1; // Increment counter normally
    end
end

endmodule

