	input 	[15:0]	data_a;
	input 	[15:0]	data_b;
	input 		wren_a;
	input 		wren_b;
	output 	[15:0]	q_a;
	output 	[15:0]	q_b;

	reg [15:0] ram [0:63];

	always @(posedge clock) begin
		if (wren_a) ram[address_a] <= data_a;
		if (wren_b) ram[address_b] <= data_b;
	end

	assign q_a = ram[address_a];
	assign q_b = ram[address_b];

endmodule

