description:
Design a 4-to-16 decoder that activates a single output line based on a 4-bit binary input when the enable signal is high. If the enable signal is low, all output lines are set to LOW. The decoder uses a bitwise left shift operation to determine which output line corresponds to the value of the binary input, producing a one-hot encoded output.
module top_module(
binary_in   , 
decoder_out , 
enable        
);

code:
module top_module(
binary_in   , 
decoder_out , 
enable        
);input [3:0] binary_in  ;
input  enable ; 
output [15:0] decoder_out ; 

wire [15:0] decoder_out ; 

assign decoder_out = (enable) ? (1 << binary_in) : 16'b0 ;

endmodule

module shift_register(
    input               clk         ,   
    input               rst         ,
    input               shift_en    ,
    input               load        ,
    input [7:0]         data_in     ,

    output reg [7:0]    data_out
);

always@(posedge clk)
begin
    if(rst)             data_out <= 8'd0;
    else if(load)       data_out <= data_in;
    else if(shift_en)   data_out <= data_out >> 1;
end

endmodule

module bin2bcd(
  input [11:0] binary_in,
  output reg [15:0] bcd_out
);

  integer i;
  reg [27:0] shift_reg; // 12 bits for binary_in + 16 bits for bcd_out

  always @(*) begin
    shift_reg = {16'd0, binary_in}; // Initialize shift register

    for (i = 0; i < 12; i = i + 1) begin
      // If any of the BCD digits is >= 5, add 3
      if (shift_reg[27:24] >= 5)
        shift_reg[27:24] = shift_reg[27:24] + 3;
      if (shift_reg[23:20] >= 5)
        shift_reg[23:20] = shift_reg[23:20] + 3;
      if (shift_reg[19:16] >= 5)
        shift_reg[19:16] = shift_reg[19:16] + 3;
      if (shift_reg[15:12] >= 5)
        shift_reg[15:12] = shift_reg[15:12] + 3;

      // Shift left by 1
      shift_reg = shift_reg << 1;
    end

    bcd_out = shift_reg[27:12]; // Extract the BCD output
  end

endmodule

