module top_module(
  input clk, reset, set_hours, set_minutes,
  output [3:0] hours, minutes
);reg [3:0] hours_reg = 4'b0000;
  reg [3:0] minutes_reg = 4'b0000;

  always @(posedge clk) begin
    if (reset) begin
      hours_reg <= 4'b0001;
      minutes_reg <= 4'b0000;
    end else begin
      if (set_hours) begin
        hours_reg <= (hours_reg == 4'b1011) ? 4'b0001 : hours_reg + 1;
      end
      if (set_minutes) begin
        minutes_reg <= (minutes_reg == 4'b1011) ? 4'b0000 : minutes_reg + 1;
      end
    end
  end

  assign hours = {hours_reg[3], hours_reg[2], hours_reg[1], hours_reg[0]};
  assign minutes = {minutes_reg[3], minutes_reg[2], minutes_reg[1], minutes_reg[0]};
endmodule

module top_module(clk, rst, load, data, count);input clk, rst, load;
  input [3:0] data;
  output [3:0] count;

  reg [3:0] count;

  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      count <= 4'b0;
    end else if (load) begin
      count <= data;
    end else begin
      count <= count + 4'b1;
    end
  end

endmodule

